11.2 Minimal Example: Cholera SIWR with Environmental Reservoir
This example shows the real-valued compartment feature (§2.1, §2.4). W is bacteria concentration in the water supply — a continuous ODE quantity, not an integer count.
{
  "name": "cholera_siwr",
  "version": "0.3",
  "description": "SIWR cholera model with environmental transmission route",

  "compartments": [
    { "name": "S", "kind": "integer" },
    { "name": "I", "kind": "integer" },
    { "name": "R", "kind": "integer" },
    { "name": "W", "kind": "real" }
  ],

  "ode_equations": [
    {
      "compartment": "W",
      "derivative": {
        "op": "sub",
        "args": [
          { "op": "mul", "args": [{ "param": "xi" }, { "pop": "I" }] },
          { "op": "mul", "args": [{ "param": "delta" }, { "pop": "W" }] }
        ]
      }
    }
  ],

  "transitions": [
    {
      "name": "infection_water",
      "stoichiometry": [["S", -1], ["I", 1]],
      "rate": {
        "op": "mul",
        "args": [
          { "pop": "S" },
          {
            "op": "div",
            "args": [
              { "op": "mul", "args": [{ "param": "beta_W" }, { "pop": "W" }] },
              { "op": "add", "args": [{ "param": "K" }, { "pop": "W" }] }
            ]
          }
        ]
      },
      "event_key": "infection_water:{firing_index}"
    },
    {
      "name": "infection_person",
      "stoichiometry": [["S", -1], ["I", 1]],
      "rate": {
        "op": "mul",
        "args": [
          { "param": "beta_P" },
          { "pop": "S" },
          {
            "op": "div",
            "args": [{ "pop": "I" }, { "pop_sum": ["S", "I", "R"] }]
          }
        ]
      },
      "event_key": "infection_person:{firing_index}"
    },
    {
      "name": "recovery",
      "stoichiometry": [["I", -1], ["R", 1]],
      "rate": { "op": "mul", "args": [{ "param": "gamma" }, { "pop": "I" }] },
      "event_key": "recovery:{firing_index}"
    }
  ],

  "parameters": [
    { "name": "beta_W", "value": 0.5, "prior": null, "transform": null },
    { "name": "beta_P", "value": 0.1, "prior": null, "transform": null },
    { "name": "K", "value": 1000000, "prior": null, "transform": null },
    { "name": "xi", "value": 10.0, "prior": null, "transform": null },
    { "name": "delta", "value": 0.2, "prior": null, "transform": null },
    { "name": "gamma", "value": 0.25, "prior": null, "transform": null }
  ],

  "initial_conditions": {
    "kind": "parameterized",
    "values": [
      ["S", { "op": "sub", "args": [{ "const": 100000 }, { "param": "I0" }] }],
      ["I", { "param": "I0" }],
      ["R", { "const": 0 }],
      ["W", { "const": 0.0 }]
    ]
  },

  "time_functions": [],
  "tables": [],
  "interventions": [],
  "observations": [],
  "data_contract": null,

  "output": {
    "times": { "kind": "regular", "start": 0, "step": 1, "end": 180 },
    "format": "tsv",
    "trajectory": true,
    "observations": false
  },

  "simulation": {
    "t_start": 0.0,
    "t_end": 180.0,
    "time_semantics": "continuous",
    "dt": null,
    "rng_seed": 42
  }
}
Note: W does not appear in any stoichiometry list. Its dynamics come entirely from ode_equations. Both transmission routes (infection_water via W and infection_person via person-to-person contact) are present; setting beta_P = 0 gives a pure waterborne model.
